const parts = msg.topic.split('/');
msg.metric = parts[1];

// Le payload peut arriver en JSON ou en valeur brute
if (typeof msg.payload === 'string') {
    try {
        msg.payload = JSON.parse(msg.payload);
    } catch (e) {
        // valeur brute (ex: "23.5"), on la laisse telle quelle
    }
}

return msg;

node.warn(`Sous-topic non géré: ${msg.topic}`);
