return msg;

const now = new Date();

const jour = String(now.getDate()).padStart(2, '0');
const mois = String(now.getMonth() + 1).padStart(2, '0'); // +1 car getMonth() va de 0 à 11
const annee = now.getFullYear();
const heures = String(now.getHours()).padStart(2, '0');
const minutes = String(now.getMinutes()).padStart(2, '0');

msg.payload = `${jour}-${mois}-${annee} ${heures}:${minutes}`;
return msg;

let value = msg.payload
node.status({});


if (isNaN(value)) {
    node.status({fill:"red",shape:"ring",text:`Valeur flux invalide pour: ${value}`});
    msg.payload =`Valeur flux invalide pour: ${value}`
} else if (value == 0) {
    msg.payload = "Flux d'eau arreté"
} else if (value == 1) {
    msg.payload = "Flux d'eau détecté"
} else if (value == 2){
    msg.payload = "Délais msg WaterPresence1 dépassé"
}else {
    msg.payload = "Statut WaterPresent non connu : " + value
}
return msg;

// Récupération des paramètres globaux
let config = global.get("Config")
var niveauHaut = config.ReservoirNiveauHaut; // valeur capteur à 100%
var niveauBas = config.ReservoirNiveauBas;   // valeur capteur à 0%

// Valeur mesurée par le capteur (distance en cm par exemple)
var mesure = msg.payload;

// Calcul du pourcentage
// Quand mesure = niveauBas  -> 0%
// Quand mesure = niveauHaut -> 100%
var pourcentage = (niveauBas - mesure) / (niveauBas - niveauHaut) * 100;

// On borne le résultat entre 0 et 100 pour éviter les valeurs aberrantes
// (ex: cuve trop pleine, capteur bruité, etc.)
pourcentage = Math.max(0, Math.min(100, pourcentage));

// Arrondi à 1 décimale (optionnel)
pourcentage = Math.round(pourcentage * 10) / 10;

msg.payload = pourcentage;

return msg;

